  ('store-dakkochi-incheon-luwon', '인천 루원 닭꼬치', 'dakkochi', '가정동 루원 대성베르힐 SK2차 사이. 금요일 제보(당근)', NULL, 'active', 'expected'),
  ('store-dakkochi-sejong-songgang', '세종 송강 닭꼬치', 'dakkochi', '송강동 그린아파트 상가 맞은편. 수 16-23시 제보(당근)', NULL, 'active', 'expected'),
