  ('store-mandu-uijeongbu-eunha', '의정부 은하수 만두', 'mandu', '신곡 은하수아파트 장날(금) 만두 포장마차/트럭 제보', NULL, 'active', 'expected'),
  ('store-mandu-incheon-juan', '인천 주안 만두트럭', 'mandu', '주안역 경향 인근 만두트럭 제보. 세븐일레븐 주안역점 쪽 원조와 구분 필요', NULL, 'active', 'unknown'),
