  ('store-chicken-seongnam-yatap', '성남 야탑 전기통닭', 'chicken', '야탑 주공8단지 벽산 사이(금), 야탑역 사거리(목) 등 순환 제보', NULL, 'active', 'expected'),
  ('store-chicken-seongnam-maehwa', '성남 매화마을 전기통닭', 'chicken', '매화마을 2단지 후문. 화요일 저녁 제보', NULL, 'active', 'expected'),
  ('store-chicken-suwon-maetan', '수원 매탄 전기통닭', 'chicken', '매탄 삼성2차 맞은편 동수원초 앞. 당근 실시간 제보', NULL, 'active', 'expected'),
  ('store-chicken-suwon-ilot', '수원 일월공원 전기통닭', 'chicken', '일월공원 시계탑 인근 자주 출몰 제보', NULL, 'active', 'expected'),
  ('store-chicken-suwon-seosuwon', '수원 서수원 전기통닭', 'chicken', '롯데백화점 서수원점 주차장 진입 사거리 제보', NULL, 'active', 'expected'),
